<script lang="ts">
 import {untrack,onMount} from 'svelte';
 import {deserialize} from '$app/forms';
 import {beforeNavigate} from '$app/navigation';
 import NewsMarkdownEditor from './NewsMarkdownEditor.svelte';
 import type {NewsPost} from '$lib/types';
 let {post,facilityId,hpPreviewSupported=false,canEdit=true,onDirty=(_v:boolean)=>{}}:{post?:NewsPost;facilityId:string;hpPreviewSupported?:boolean;canEdit?:boolean;onDirty?:(v:boolean)=>void}=$props();
 let id=$state(untrack(()=>post?.id??'')),title=$state(untrack(()=>post?.title??'')),body=$state(untrack(()=>(post?.body??'').replace(/\r\n?/g,'\n'))),publishedAt=$state(untrack(()=>post?.publishedAt??new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Tokyo'}).format(new Date()))),published=$state(untrack(()=>post?.isPublished??false));
 const snapshot=()=>JSON.stringify({title,body,publishedAt});
 let saved=$state(untrack(snapshot)),saving=$state(false),busy=$state(false),uploading=$state(false),error=$state(''),ready=$state(false);
 let flight:Promise<boolean>|null=null,formEl:HTMLFormElement;
 const dirty=$derived(snapshot()!==saved),locked=$derived(busy||uploading||!canEdit);
 onMount(()=>{ready=true;return()=>{ready=false;};});
 $effect(()=>onDirty(dirty));
 $effect(()=>{const changed=snapshot();if(!ready||!canEdit||uploading||changed===saved)return;const timer=setTimeout(()=>void persist(),900);return()=>clearTimeout(timer);});
 beforeNavigate(nav=>{if((dirty||uploading||saving)&&!confirm('まだ保存していない変更があります。移動しますか？'))nav.cancel();});
 async function action(kind:string,form:FormData){const response=await fetch('/admin/news?/'+kind,{method:'POST',body:form,headers:{accept:'application/json','x-sveltekit-action':'true'},signal:AbortSignal.timeout(25000)});const result=deserialize(await response.text());if(result.type!=='success')throw Error(result.type==='failure'?String(result.data?.message??'保存できません。'):'保存できません。');return result.data;}
 function payload(){const f=new FormData();f.set('facilityId',facilityId);if(id)f.set('postId',id);f.set('title',title.trim()||'無題のお知らせ');f.set('body',body);f.set('publishedAt',publishedAt);return f;}
 async function persist():Promise<boolean>{if(!canEdit||uploading)return false;if(flight){if(!await flight)return false;if(snapshot()!==saved)return persist();return !error;}if(snapshot()===saved&&id)return true;const pending=snapshot(),form=payload();saving=true;error='';flight=(async()=>{try{const data=await action('autosave',form);if(typeof data?.saved!=='string')throw Error('保存結果を確認できません。');id=data.saved;saved=pending;return true;}catch(e){error=e instanceof Error?e.message:'自動保存できません。';return false;}finally{saving=false;flight=null;}})();return flight;}
 async function changePublication(){if(locked||!await persist())return;busy=true;error='';try{const f=payload();if(!published)f.set('isPublished','on');await action('save',f);published=!published;}catch(e){error=e instanceof Error?e.message:'公開状態を変更できません。';}finally{busy=false;}}
 async function preview(){if(locked)return;const popup=window.open('about:blank','_blank');if(!popup){error='プレビューのポップアップを許可してください。';return;}popup.opener=null;busy=true;try{if(!await persist())throw Error(error||'自動保存を確認してください。');const data=await action('preview',payload());const url=new URL(String(data?.previewUrl));if(url.origin!=='https://www.yamado.co.jp')throw Error('プレビューURLを確認できません。');popup.location.href=url.href;}catch(e){popup.close();error=e instanceof Error?e.message:'プレビューを開けません。';}finally{busy=false;}}
</script>
<form bind:this={formEl} class="news-post-editor" aria-label={post?'お知らせを編集':'新しいお知らせ'} onsubmit={e=>{e.preventDefault();void persist();}}>
 <div class="post-fields"><label class="title-field">タイトル<input bind:value={title} maxlength="200" placeholder="お知らせのタイトル" disabled={locked}/></label><label>掲載日<input type="date" bind:value={publishedAt} disabled={locked}/></label><span class="publication">{published?'公開中':'下書き'}</span></div>
 <NewsMarkdownEditor bind:value={body} {facilityId} disabled={busy||!canEdit} onBusy={v=>uploading=v} onSave={()=>void persist()}/>
 <div class="post-editor-footer"><span class:unsaved={dirty} role="status">{error?'保存に失敗しました':uploading?'画像を追加中…':saving?'自動保存中…':dirty?'変更を保存します…':id?'自動保存・保存済み':'入力すると自動保存します'}</span><div>{#if hpPreviewSupported&&canEdit&&!published}<button type="button" class="preview-button" disabled={locked} onclick={()=>void preview()}>HPでプレビュー ↗</button>{:else if hpPreviewSupported&&published}<a class="preview-button" href={'https://www.yamado.co.jp/news/'+id+'/'} target="_blank" rel="noopener noreferrer">HPで確認 ↗</a>{/if}{#if canEdit}<button type="button" class="preview-button" disabled={locked} onclick={()=>void persist()}>今すぐ保存</button><button type="button" class="save-button" disabled={locked||saving} onclick={()=>void changePublication()}>{published?'非公開に戻す':'公開する'}</button>{/if}</div></div>
 {#if error}<p class="post-error" role="alert">{error} <button type="button" onclick={()=>void persist()}>再試行</button></p>{/if}
</form>
<style>
.news-post-editor{padding:1.3rem;background:#fff;color:#3c5134}.post-fields{display:flex;gap:1rem;align-items:flex-end;margin-bottom:1.1rem;flex-wrap:wrap}.post-fields label{display:grid;gap:.4rem;font-size:.7rem;color:#829073}.post-fields .title-field{flex:1;min-width:250px}.post-fields input:not([type=checkbox]){background:#fff;border:1px solid #dbe2d3;border-radius:.5rem;padding:.65rem .75rem;color:#3b5133;font-size:.83rem}.post-fields .publication{display:flex;align-items:center;gap:.45rem;padding-bottom:.65rem;font-size:.75rem}.post-editor-footer{display:flex;justify-content:space-between;align-items:center;gap:1rem;margin-top:1rem}.post-editor-footer>span{font-size:.68rem;color:#92a17f}.post-editor-footer>.unsaved{color:#b58a49}.post-editor-footer>div{display:flex;gap:.6rem;align-items:center;flex-wrap:wrap}.post-editor-footer button,.preview-button{border:1px solid #d9e2cf;border-radius:.5rem;padding:.65rem .9rem;font-size:.75rem;transition:background .15s,box-shadow .15s,transform .15s}.preview-button{background:#fff;color:#6b8558}.preview-button:hover:not(:disabled){background:#eef4e6;border-color:#a9be94;box-shadow:0 2px 7px #38502b18}.post-editor-footer .save-button{background:#57764a;border-color:#57764a;color:#fff}.save-button:hover:not(:disabled){background:#3e5c31;box-shadow:0 3px 9px #304a2425;transform:translateY(-1px)}button:disabled{opacity:.45;cursor:default}.post-error{font-size:.75rem;line-height:1.8;padding:.8rem 1rem;margin-top:1rem;border-radius:.55rem}.post-error{color:#a66746;background:#fff1e8}input:focus-visible,button:focus-visible,a:focus-visible{outline:2px solid #86a36c;outline-offset:2px}.post-fields .title-field{flex:1 0 100%}.post-fields .title-field input{font-size:1.65rem;font-weight:600;border:0;border-radius:0;padding:.3rem 0;letter-spacing:-.02em}.post-fields .title-field input:focus{outline:none;box-shadow:0 1px 0 #9fac8f}.post-fields{padding:10px 8px 20px;gap:16px}.post-fields .publication{color:#8c987e}.news-post-editor{padding:1.5rem}.post-editor-footer{padding:4px 8px}@media(max-width:650px){.news-post-editor{padding:1rem}.post-fields{gap:.8rem}.post-fields .title-field{min-width:100%;width:100%}.post-editor-footer{align-items:flex-start;flex-direction:column}.post-editor-footer>div{width:100%}.post-editor-footer .save-button{margin-left:auto}.preview-button{font-size:.7rem}}
</style>
